// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(address depositor, uint256 amt) internal {
        amt = bound(amt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amt);
        depositor = address(this);
        uint256 oldBal;
        try c.balances(depositor) returns (uint256 __r) { oldBal = __r; } catch { return; }
        try c.Deposit{value: amt}() {} catch { return; }
        uint256 newBal;
        try c.balances(depositor) returns (uint256 __r) { newBal = __r; } catch { return; }
        assertTrue(newBal == oldBal + amt);
    }

    function testFuzz_run(address depositor, uint256 amt) public {
        _run(depositor, amt);
    }

    receive() external payable {}
}
